# Register scheduled task(s) for the auto-dial script.
# Reads $connName from config.ps1 (generated by install.ps1).
# Usage: .\register-task.ps1 [-Reconnect]
#   -Reconnect : also re-dial when the connection drops (checks every 3 minutes)
param([switch]$Reconnect)

$ErrorActionPreference = 'Stop'
$dialScript = Join-Path $PSScriptRoot 'dial.ps1'
$configFile = Join-Path $PSScriptRoot 'config.ps1'

if (-not (Test-Path $configFile)) { Write-Host 'ERROR: config.ps1 not found - run install.ps1 first.'; exit 1 }
. $configFile
if (-not $connName) { Write-Host 'ERROR: $connName missing in config.ps1'; exit 1 }
$taskName = "AutoDial-$connName"

# launch via wscript (hidden VBS wrapper) so no console window flashes on each trigger
$action    = New-ScheduledTaskAction -Execute 'wscript.exe' -Argument ('//B //Nologo "{0}"' -f (Join-Path $PSScriptRoot 'dial-hidden.vbs'))
$principal = New-ScheduledTaskPrincipal -UserId $env:USERNAME -LogonType Interactive -RunLevel Limited
$settings  = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable -ExecutionTimeLimit (New-TimeSpan -Minutes 5)

$intervalSec = [int]$reconnectSeconds
if ($intervalSec -lt 10) { $intervalSec = 10 }

$triggers = @()
$triggers += New-ScheduledTaskTrigger -AtLogOn -User $env:USERNAME
$desc = 'logon only'
if ($Reconnect) {
    $duration = New-TimeSpan -Days 3650
    if ($intervalSec -gt 60) {
        $minutes = [int][math]::Round($intervalSec / 60)
        if ($minutes -lt 1) { $minutes = 1 }
        $triggers += New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes($minutes) -RepetitionInterval (New-TimeSpan -Minutes $minutes) -RepetitionDuration $duration
        $desc = "every $minutes min"
    }
    else {
        # Task Scheduler enforces a 1-minute minimum repetition interval.
        # Stagger N triggers (each repeating every 1 min) for shorter effective intervals.
        $count = [int][math]::Floor(60 / $intervalSec)
        for ($i = 1; $i -le $count; $i++) {
            $triggers += New-ScheduledTaskTrigger -Once -At (Get-Date).AddSeconds($i * $intervalSec) -RepetitionInterval (New-TimeSpan -Minutes 1) -RepetitionDuration $duration
        }
        $desc = "every $intervalSec sec"
        if ($count -gt 1) { $desc += " (via $count staggered triggers)" }
    }
}

Register-ScheduledTask -TaskName $taskName -Action $action -Trigger $triggers -Principal $principal -Settings $settings -Force | Out-Null

if ($Reconnect) { Write-Host "Task '$taskName' registered (logon + reconnect check $desc)." }
else { Write-Host "Task '$taskName' registered (logon only)." }
